//! Differential parity for R10 cleanup/retention plus workspace/lock lifecycle.
//!
//! Fixtures were generated by `fixtures_cleanup.py`: the Python modules ran on temporary
//! copies with a pinned clock, and every absolute prefix was rewritten to `<TREE>`.
//! This test rebuilds the same trees from the recorded contents, calls the Rust port
//! with the same clock and applies the same prefix rewrite.

use std::path::{Path, PathBuf};

use sd_core::clock::{Clock, FixedClock};
use sd_storage::cleanup::{
    cleanup_analysis, cleanup_owned_run, read_receipt, receipt_data, sweep_orphans, CleanupOptions,
    UnwiredGate,
};
use sd_storage::locks::{
    acquire_cleanup_lock, parse_marker, pid_is_running, pid_status, read_pipeline_pid,
    write_pipeline_marker, ProcessStatus,
};
use sd_storage::retention::{
    gc_runtime, is_run_id, prune_cache, sweep_legacy_snapshots, GcOptions,
};
use sd_storage::run_workspace::{
    create_run_workspace, mark_run_failed, release_pipeline_lock, update_run_workspace,
};
use serde_json::Value;

const FIXED_NOW: &str = "2026-01-05T00:00:00Z";
const GC_OLD_NOW: &str = "2030-01-01T00:00:00Z";
const GC_EPOCH_NOW: &str = "1970-01-01T00:00:00Z";

fn fixture() -> Value {
    let path =
        Path::new(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/cleanup/cleanup.json");
    serde_json::from_str(&std::fs::read_to_string(path).expect("fixture")).expect("json")
}

fn fixture_tree(name: &str) -> serde_json::Map<String, Value> {
    let path = Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../tests/fixtures/cleanup")
        .join(name);
    serde_json::from_str::<Value>(&std::fs::read_to_string(path).expect("tree fixture"))
        .expect("json")
        .as_object()
        .expect("tree object")
        .clone()
}

fn temp_root(name: &str) -> PathBuf {
    let path = std::env::temp_dir().join(format!("sd-r10-{}-{name}", std::process::id()));
    let _ = std::fs::remove_dir_all(&path);
    path
}

fn write_map(root: &Path, files: &serde_json::Map<String, Value>) {
    for (relative, content) in files {
        let path = root.join(relative);
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent).expect("dirs");
        }
        let text = content.as_str().unwrap_or_default();
        std::fs::write(&path, text).expect("fixture file");
    }
}

fn write_tree(root: &Path, tree: &Value) {
    if let Some(directories) = tree.get("directories").and_then(Value::as_array) {
        for directory in directories {
            if let Some(name) = directory.as_str() {
                std::fs::create_dir_all(root.join(name)).expect("dirs");
            }
        }
    }
    if let Some(files) = tree.get("files").and_then(Value::as_object) {
        write_map(root, files);
    }
}

fn normalize_text(text: &str, prefix: &Path) -> String {
    let canonical = prefix
        .canonicalize()
        .unwrap_or_else(|_| prefix.to_path_buf());
    let plain = prefix.to_string_lossy().to_string();
    let canonical = canonical.to_string_lossy().to_string();
    let canonical = canonical
        .strip_prefix(r"\\?\")
        .unwrap_or(&canonical)
        .to_string();
    let mut mapped = text.replace(r"\\?\", "");
    // Replace the canonical (longer) form first. On macOS the temp directory is usually
    // a symlinked path (`/var/...`) whose canonical form is `/private/var/...`; replacing
    // the shorter plain form first would leave a stray `/private` prefix in the fixture
    // comparison. Both forms are still normalized on every supported host.
    if canonical != plain {
        mapped = mapped.replace(&canonical, "<TREE>");
    }
    mapped = mapped.replacen(&plain, "<TREE>", 1);
    mapped.replace('\\', "/")
}

fn normalize(value: &Value, prefix: &Path) -> Value {
    match value {
        Value::String(text) => Value::String(normalize_text(text, prefix)),
        Value::Array(items) => {
            Value::Array(items.iter().map(|item| normalize(item, prefix)).collect())
        }
        Value::Object(map) => Value::Object(
            map.iter()
                .map(|(key, item)| (key.clone(), normalize(item, prefix)))
                .collect(),
        ),
        other => other.clone(),
    }
}

fn with_generated_at(value: &Value) -> Value {
    let mut mapped = value.clone();
    if let Some(map) = mapped.as_object_mut() {
        map.insert("generated_at_utc".into(), Value::String("FIXED".into()));
    }
    mapped
}

fn assert_json_close(actual: &Value, expected: &Value, path: &str) {
    match (actual, expected) {
        (Value::Number(left), Value::Number(right)) => {
            let left_value = left.as_f64().expect("number");
            let right_value = right.as_f64().expect("number");
            let tolerance = 1e-12 * right_value.abs().max(1.0);
            assert!(
                (left_value - right_value).abs() <= tolerance,
                "{path}: {left_value} vs {right_value}"
            );
        }
        (Value::Array(left), Value::Array(right)) => {
            assert_eq!(left.len(), right.len(), "{path}: array length differs");
            for (index, (actual_item, expected_item)) in left.iter().zip(right.iter()).enumerate() {
                assert_json_close(actual_item, expected_item, &format!("{path}[{index}]"));
            }
        }
        (Value::Object(left), Value::Object(right)) => {
            assert_eq!(
                left.len(),
                right.len(),
                "{path}: object size differs ({:?} vs {:?})",
                left.keys().collect::<Vec<_>>(),
                right.keys().collect::<Vec<_>>()
            );
            for (key, expected_item) in right.iter() {
                let actual_item = left
                    .get(key)
                    .unwrap_or_else(|| panic!("{path}: missing key {key}"));
                assert_json_close(actual_item, expected_item, &format!("{path}/{key}"));
            }
        }
        _ => assert_eq!(actual, expected, "{path}: value differs"),
    }
}

#[test]
fn receipts_match_python() {
    let document = fixture();
    let expected = &document["receipt"];
    let text = expected["text"].as_str().expect("receipt text");
    let decoded = read_receipt(&{
        let path = temp_root("receipt").join("valid.txt");
        std::fs::create_dir_all(path.parent().expect("parent")).expect("dirs");
        std::fs::write(&path, text).expect("write");
        path
    })
    .expect("receipt");
    assert_json_close(&decoded.to_value(), &expected["read"], "receipt/read");
    assert_eq!(
        decoded.to_value().get("targets"),
        expected["read"].get("targets")
    );

    // Re-formatting the parsed values reproduces the same text (clock injected).
    let targets: Vec<(String, String, i64)> = decoded
        .targets
        .iter()
        .map(|(name, digest, size)| (name.clone(), digest.clone(), *size))
        .collect();
    let regenerated = receipt_data(
        "run",
        "run_20260101T000000000000Z_abcdef12",
        Some("analysis_x"),
        Some("snap_x"),
        Some("collection_x.json"),
        "complete",
        Some(&"c".repeat(64)),
        None,
        Some(&"d".repeat(64)),
        Some("success"),
        Some("reportable"),
        &targets,
        decoded
            .get("removed_file_count")
            .and_then(Value::as_str)
            .and_then(|value| value.parse::<i64>().ok())
            .unwrap_or(0),
        decoded
            .get("removed_json_bytes")
            .and_then(Value::as_str)
            .and_then(|value| value.parse::<i64>().ok())
            .unwrap_or(0),
        &[],
        "verified",
        FIXED_NOW,
    );
    assert_eq!(regenerated, text);

    for (name, expected_error) in document["receipt_errors"].as_object().expect("errors") {
        let body = match name.as_str() {
            "bad_format" => text.replace("format=stock-data-cleanup-v1", "format=nope"),
            "bad_state" => text.replace("state=complete", "state=weird"),
            "bad_delivery" => text.replace("delivery=verified", "delivery=maybe"),
            "bad_digest" => text.replace(&"a".repeat(64), "zz"),
            "bad_totals" => text.replace("target_file_count=2", "target_file_count=3"),
            "complete_missing" => text.replace("removed_file_count=2", "removed_file_count=1"),
            "target_path" => text.replace("target=analysis.json", "target=../analysis.json"),
            "duplicate" => format!("{text}target=analysis.json\t{}\t1\n", "e".repeat(64)),
            other => panic!("unexpected receipt case {other}"),
        };
        let path = temp_root(&format!("receipt-{name}")).join("bad.txt");
        std::fs::create_dir_all(path.parent().expect("parent")).expect("dirs");
        std::fs::write(&path, body).expect("write");
        let actual = read_receipt(&path).expect_err(name);
        assert_eq!(
            actual,
            expected_error.as_str().unwrap_or_default(),
            "receipt case {name}"
        );
    }
}

#[test]
fn orphan_sweep_matches_python() {
    let document = fixture();
    let expected = &document["orphan"];
    let source = temp_root("orphan-src");
    write_map(&source, &fixture_tree("orphan_src_files.json"));
    let work = temp_root("orphan-work");
    std::fs::create_dir_all(&work).expect("work");
    copy_tree(&source, &work);
    let dry = sweep_orphans(&work, true).expect("dry");
    assert_json_close(
        &normalize(&dry, &work),
        &expected["dry_run"],
        "orphan/dry_run",
    );
    let real = sweep_orphans(&work, false).expect("real");
    assert_json_close(
        &normalize(&real, &work),
        &expected["removed"],
        "orphan/removed",
    );
    let mut remaining: Vec<String> = walk_files(&work)
        .into_iter()
        .map(|path| {
            path.strip_prefix(&work)
                .unwrap_or(&path)
                .to_string_lossy()
                .replace('\\', "/")
        })
        .collect();
    remaining.sort();
    let expected_remaining: Vec<String> = expected["remaining"]
        .as_array()
        .expect("remaining")
        .iter()
        .filter_map(Value::as_str)
        .map(ToString::to_string)
        .collect();
    assert_eq!(remaining, expected_remaining);
}

fn copy_tree(from: &Path, to: &Path) {
    for entry in std::fs::read_dir(from).expect("read") {
        let entry = entry.expect("entry");
        let target = to.join(entry.file_name());
        if entry.path().is_dir() {
            std::fs::create_dir_all(&target).expect("dir");
            copy_tree(&entry.path(), &target);
        } else {
            std::fs::copy(entry.path(), &target).expect("copy");
        }
    }
}

fn walk_files(root: &Path) -> Vec<PathBuf> {
    let mut files = Vec::new();
    let mut stack = vec![root.to_path_buf()];
    while let Some(current) = stack.pop() {
        for entry in std::fs::read_dir(&current).expect("read") {
            let entry = entry.expect("entry");
            let path = entry.path();
            if path.is_dir() {
                stack.push(path);
            } else {
                files.push(path);
            }
        }
    }
    files
}

#[test]
fn analysis_cleanup_matches_python() {
    let document = fixture();
    let expected = &document["analysis"];
    let files = &fixture_tree("analysis_src_files.json");
    let work_root = temp_root("analysis-work");
    let work = work_root.join("analysis_work");
    std::fs::create_dir_all(&work).expect("analysis dir");
    write_map(&work, files);
    let clock = FixedClock::from_timestamp(FIXED_NOW).expect("clock");
    let options = |dry_run: bool| CleanupOptions {
        dry_run,
        force_incomplete: true,
        delivery_unverified: false,
    };
    let dry = cleanup_analysis(&work, None, &options(true), &clock, &UnwiredGate).expect("dry");
    assert_json_close(
        &normalize(&dry, &work),
        &expected["dry_run"],
        "analysis/dry_run",
    );
    let cleaned =
        cleanup_analysis(&work, None, &options(false), &clock, &UnwiredGate).expect("clean");
    assert_json_close(
        &normalize(&cleaned, &work),
        &expected["clean"],
        "analysis/clean",
    );
    let receipt_text = std::fs::read_to_string(work.join("cleanup_receipt.txt")).expect("receipt");
    assert_eq!(normalize_text(&receipt_text, &work), expected["receipt"]);
    let again =
        cleanup_analysis(&work, None, &options(false), &clock, &UnwiredGate).expect("again");
    assert_json_close(
        &normalize(&again, &work),
        &expected["already_cleaned"],
        "analysis/again",
    );
    let mut remaining: Vec<String> = walk_files(&work)
        .into_iter()
        .map(|path| {
            path.strip_prefix(&work)
                .unwrap_or(&path)
                .to_string_lossy()
                .replace('\\', "/")
        })
        .collect();
    remaining.sort();
    let expected_remaining: Vec<String> = expected["remaining"]
        .as_array()
        .expect("remaining")
        .iter()
        .filter_map(Value::as_str)
        .map(ToString::to_string)
        .collect();
    assert_eq!(remaining, expected_remaining);

    let unknown_root = temp_root("analysis-unknown");
    let unknown = unknown_root.join("analysis_x");
    std::fs::create_dir_all(&unknown).expect("unknown dir");
    write_map(&unknown, files);
    std::fs::write(unknown.join("mystery.json"), "{}").expect("unknown");
    assert_eq!(
        cleanup_analysis(&unknown, None, &options(false), &clock, &UnwiredGate)
            .expect_err("unknown"),
        expected["unknown_error"].as_str().expect("error")
    );
    let fresh_root = temp_root("analysis-missing-response");
    let fresh = fresh_root.join("analysis_x");
    std::fs::create_dir_all(&fresh).expect("fresh dir");
    write_map(&fresh, files);
    assert_eq!(
        cleanup_analysis(
            &fresh,
            None,
            &CleanupOptions::default(),
            &clock,
            &UnwiredGate
        )
        .expect_err("missing response"),
        expected["missing_response_error"].as_str().expect("error")
    );
}

#[test]
fn owned_run_cleanup_matches_python() {
    let document = fixture();
    let expected = &document["owned_run"];
    let files = &fixture_tree("run_src_files.json");
    let run_id = "run_20260101T000000000000Z_abcdef12";
    let clock = FixedClock::from_timestamp(FIXED_NOW).expect("clock");
    let options = |dry_run: bool| CleanupOptions {
        dry_run,
        force_incomplete: true,
        delivery_unverified: false,
    };
    let root = temp_root("run-work");
    let run = root.join(run_id);
    std::fs::create_dir_all(&run).expect("run dir");
    write_map(&run, files);
    let dry =
        cleanup_owned_run(&run, None, None, &options(true), &clock, &UnwiredGate).expect("dry");
    assert_json_close(&normalize(&dry, &run), &expected["dry_run"], "run/dry_run");
    let cleaned =
        cleanup_owned_run(&run, None, None, &options(false), &clock, &UnwiredGate).expect("clean");
    assert_json_close(&normalize(&cleaned, &run), &expected["clean"], "run/clean");
    let receipt_text = std::fs::read_to_string(run.join("cleanup_receipt.txt")).expect("receipt");
    assert_eq!(normalize_text(&receipt_text, &run), expected["receipt"]);
    let again =
        cleanup_owned_run(&run, None, None, &options(false), &clock, &UnwiredGate).expect("again");
    assert_json_close(
        &normalize(&again, &run),
        &expected["already_cleaned"],
        "run/again",
    );
    let mut remaining: Vec<String> = walk_files(&run)
        .into_iter()
        .map(|path| {
            path.strip_prefix(&run)
                .unwrap_or(&path)
                .to_string_lossy()
                .replace('\\', "/")
        })
        .collect();
    remaining.sort();
    let expected_remaining: Vec<String> = expected["remaining"]
        .as_array()
        .expect("remaining")
        .iter()
        .filter_map(Value::as_str)
        .map(ToString::to_string)
        .collect();
    assert_eq!(remaining, expected_remaining);

    let unknown_root = temp_root("run-unknown");
    let unknown = unknown_root.join(run_id);
    std::fs::create_dir_all(&unknown).expect("unknown dir");
    write_map(&unknown, files);
    std::fs::write(unknown.join("data.json"), "{}").expect("unknown");
    assert_eq!(
        cleanup_owned_run(&unknown, None, None, &options(false), &clock, &UnwiredGate)
            .expect_err("unknown"),
        expected["unknown_error"].as_str().expect("error")
    );
    let blocked_root = temp_root("run-blocked");
    let blocked = blocked_root.join(run_id);
    std::fs::create_dir_all(&blocked).expect("blocked dir");
    write_map(&blocked, files);
    assert_eq!(
        cleanup_owned_run(
            &blocked,
            None,
            None,
            &CleanupOptions::default(),
            &clock,
            &UnwiredGate
        )
        .expect_err("not complete"),
        expected["not_complete_error"].as_str().expect("error")
    );

    // The retained-snapshot layout only gets a dry run (the frozen receipts stay).
    let retained_root = temp_root("run-retained");
    let retained = retained_root.join(run_id);
    std::fs::create_dir_all(&retained).expect("retained dir");
    write_map(&retained, &fixture_tree("run_retained_files.json"));
    let retained_dry =
        cleanup_owned_run(&retained, None, None, &options(true), &clock, &UnwiredGate)
            .expect("retained dry");
    assert_json_close(
        &normalize(&retained_dry, &retained),
        &expected["retained_dry_run"],
        "run/retained_dry_run",
    );
}

#[test]
fn gc_matches_python() {
    let document = fixture();
    let expected = &document["gc"];
    let build = |name: &str| {
        let root = temp_root(name);
        std::fs::create_dir_all(&root).expect("root");
        write_tree(&root, &document["gc_files"]);
        root
    };
    let clock = FixedClock::from_timestamp(GC_OLD_NOW).expect("clock");
    let old_root = build("gc-old");
    let old = gc_runtime(
        &old_root,
        &GcOptions {
            retain_days: 30,
            cache_days: 7,
            pending_days: 0,
            cache_dir: None,
            dry_run: false,
            throttle_hours: None,
        },
        &clock,
        &UnwiredGate,
    )
    .expect("old");
    assert_json_close(
        &normalize(&with_generated_at(&old), &old_root),
        &expected["old"],
        "gc/old",
    );

    let epoch_clock = FixedClock::from_timestamp(GC_EPOCH_NOW).expect("clock");
    let epoch_root = build("gc-epoch");
    let epoch = gc_runtime(
        &epoch_root,
        &GcOptions {
            retain_days: 30,
            cache_days: 7,
            pending_days: 0,
            cache_dir: None,
            dry_run: false,
            throttle_hours: None,
        },
        &epoch_clock,
        &UnwiredGate,
    )
    .expect("epoch");
    assert_json_close(
        &normalize(&with_generated_at(&epoch), &epoch_root),
        &expected["epoch"],
        "gc/epoch",
    );

    let throttle_root = build("gc-throttle");
    let fresh_clock = FixedClock::from_timestamp(GC_OLD_NOW).expect("clock");
    let throttled = gc_runtime(
        &throttle_root,
        &GcOptions {
            retain_days: 30,
            cache_days: 7,
            pending_days: 0,
            cache_dir: None,
            dry_run: false,
            throttle_hours: Some(24.0),
        },
        &fresh_clock,
        &UnwiredGate,
    )
    .expect("throttled");
    assert_json_close(
        &normalize(&throttled, &throttle_root),
        &expected["throttled"],
        "gc/throttled",
    );
    std::fs::write(
        throttle_root.join(".gc_state.json"),
        serde_json::json!({"format": "stock-data-gc-v1", "last_run_utc": "2020-01-01T00:00:00Z"})
            .to_string(),
    )
    .expect("state");
    let unthrottled = gc_runtime(
        &throttle_root,
        &GcOptions {
            retain_days: 30,
            cache_days: 7,
            pending_days: 0,
            cache_dir: None,
            dry_run: false,
            throttle_hours: Some(24.0),
        },
        &fresh_clock,
        &UnwiredGate,
    )
    .expect("unthrottled");
    assert_json_close(
        &normalize(&with_generated_at(&unthrottled), &throttle_root),
        &expected["unthrottled"],
        "gc/unthrottled",
    );

    let dry_root = build("gc-dry");
    let dry = gc_runtime(
        &dry_root,
        &GcOptions {
            retain_days: 30,
            cache_days: 7,
            pending_days: 0,
            cache_dir: None,
            dry_run: true,
            throttle_hours: None,
        },
        &clock,
        &UnwiredGate,
    )
    .expect("dry");
    assert_json_close(
        &normalize(&with_generated_at(&dry), &dry_root),
        &expected["dry_run"],
        "gc/dry_run",
    );
}

#[test]
fn workspace_and_locks_lifecycle() {
    let root = temp_root("workspace");
    std::fs::create_dir_all(&root).expect("root");
    let clock = FixedClock::from_timestamp(FIXED_NOW).expect("clock");
    let run_id = "run_20260101T000000000000Z_abcdef12";
    let (run_dir, manifest) =
        create_run_workspace(&root, &clock, Some(run_id)).expect("create workspace");
    assert!(run_dir.ends_with(run_id));
    assert_eq!(manifest["manifest_version"], 1);
    assert_eq!(manifest["mode"], "owned_pipeline");
    assert_eq!(manifest["state"], "running");
    assert_eq!(manifest["created_at_utc"], FIXED_NOW);
    assert!(is_run_id(run_id));
    assert_eq!(
        read_pipeline_pid(&run_dir).expect("pid"),
        std::process::id() as i64
    );
    assert!(pid_is_running(std::process::id() as i64).expect("running"));
    assert!(!pid_is_running(999_999).expect("dead pid"));

    let mut updates = serde_json::Map::new();
    updates.insert("state".into(), Value::String("awaiting_cleanup".into()));
    updates.insert("analysis_id".into(), Value::String("analysis_x".into()));
    let updated = update_run_workspace(&run_dir, &updates).expect("update");
    assert_eq!(updated["state"], "awaiting_cleanup");
    assert_eq!(updated["analysis_id"], "analysis_x");

    mark_run_failed(&run_dir, "RuntimeError");
    let manifest =
        sd_storage::jsonio::read_json_file(&run_dir.join("run_manifest.json")).expect("manifest");
    assert_eq!(manifest["state"], "failed");
    assert_eq!(manifest["failure_type"], "RuntimeError");
    assert!(!run_dir.join(".pipeline.lock").exists());

    write_pipeline_marker(&run_dir, 999_999).expect("marker");
    release_pipeline_lock(&run_dir).expect("release");
    release_pipeline_lock(&run_dir).expect("release idempotent");
    assert!(parse_marker("pid=123\n").is_some());
    assert!(parse_marker("pid=0\n").is_none());
    assert!(parse_marker("nope").is_none());

    let lock_path = root.join("runs").join(".shared.cleanup.lock");
    let guard = acquire_cleanup_lock(&lock_path).expect("first lock");
    assert!(
        acquire_cleanup_lock(&lock_path).is_err(),
        "second lock must contend"
    );
    drop(guard);
    let _guard = acquire_cleanup_lock(&lock_path).expect("lock after release");
    let marker_len = std::fs::metadata(&lock_path).expect("lock file").len();
    assert!(marker_len > 0, "lock marker must carry the holder pid");

    // Retention helpers: cache pruning and legacy snapshot ages are observable.
    let cache = root.join("cache");
    std::fs::create_dir_all(cache.join("nested")).expect("cache");
    std::fs::write(cache.join("nested").join("old.json"), "{}").expect("cache file");
    let future = FixedClock::from_timestamp(GC_OLD_NOW).expect("clock");
    let pruned = prune_cache(&cache, 7, false, future.now()).expect("prune");
    assert!(pruned["files_removed"].as_i64().unwrap_or(0) >= 1);
    let epoch = FixedClock::from_timestamp(GC_EPOCH_NOW).expect("clock");
    let untouched = prune_cache(&cache, 7, false, epoch.now()).expect("prune epoch");
    assert_eq!(untouched["files_removed"], 0);
    let snapshot_root = root.join("snapshots");
    std::fs::create_dir_all(snapshot_root.join(".snap.abcdefgh")).expect("snapshot scratch");
    std::fs::write(snapshot_root.join(".snap.abcdefgh").join("x.json"), "{}").expect("file");
    let swept = sweep_legacy_snapshots(&root, 1.0, false, future.now()).expect("snapshot sweep");
    assert!(swept["removed"].as_array().expect("removed").len() == 1);
}

#[test]
fn liveness_is_tri_valued_and_unknown_is_not_dead() {
    // The current process is alive even when no process-listing tool is on PATH.
    assert_eq!(
        pid_status(std::process::id() as i64).expect("status"),
        ProcessStatus::Alive
    );
    assert_eq!(pid_status(999_999).expect("status"), ProcessStatus::Dead);
    assert!(!pid_is_running(999_999).expect("dead"));
    // Unknown must be surfaced as an error (fail closed), never as a boolean `dead`.
    let entries = std::fs::read_dir(std::env::temp_dir()).expect("temp");
    assert!(entries.into_iter().next().is_some());
    assert!(pid_is_running(-1).is_err());
}
